-- SELECT only. 20261128120000_mcp_claude_attach 적용 뒤. 카탈로그·migration 기록만 읽는다(행 값 없음).
-- 예/아니오 항목은 모두 예, 해시는 precheck의 같은 이름 항목과 같은 값이어야 한다.
-- expect: history row present = 예
-- expect: log file columns and checks = 예
-- expect: gate accepts attach tools = 예
-- expect: undo refuses attach rows = 예
-- expect: attach check invoker authenticated only = 예
-- expect: attach commit definer service role only = 예
-- expect: attach undone invoker authenticated only = 예
-- expect: log table privileges unchanged = 예
-- expect: existing boundary hash = 기록
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261128120000' and name='mcp_claude_attach')=1 then '예' else '아니오' end as ok
union all select 'log file columns and checks',case when (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_write_log') and ((a.attname='files' and a.atttypid='jsonb'::regtype) or (a.attname='file_bytes' and a.atttypid='bigint'::regtype)) and not a.attnotnull and not a.attisdropped)=2 and (select count(*) from pg_constraint c where c.conrelid=to_regclass('public.app_mcp_write_log') and c.contype='c' and ((c.conname='app_mcp_write_log_tool_check' and pg_get_constraintdef(c.oid) ~ 'web2_attach_drive_file') or (c.conname='app_mcp_write_log_action_check' and pg_get_constraintdef(c.oid) ~ '''attach''') or c.conname='app_mcp_write_log_files_check'))=3 then '예' else '아니오' end
union all select 'gate accepts attach tools',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('private.app_mcp_write_gate(text)') and p.prosecdef and p.proconfig=array['search_path=""'] and pg_get_functiondef(p.oid) like '%web2_attach_file%' and pg_get_functiondef(p.oid) like '%web2_attach_drive_file%' and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute')) then '예' else '아니오' end
union all select 'undo refuses attach rows',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_mcp_write_undo(uuid)') and not p.prosecdef and pg_get_functiondef(p.oid) like '%v_log.action = ''attach''%' and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute')) then '예' else '아니오' end
union all select 'attach check invoker authenticated only',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_mcp_attach_check(text,jsonb)') and not p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0)) then '예' else '아니오' end
union all select 'attach commit definer service role only',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_mcp_attach_commit(uuid,uuid,timestamptz,jsonb)') and p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('service_role',p.oid,'execute') and not has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0)) then '예' else '아니오' end
union all select 'attach undone invoker authenticated only',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_mcp_attach_undone(uuid)') and not p.prosecdef and p.proconfig=array['search_path=""'] and has_function_privilege('authenticated',p.oid,'execute') and not has_function_privilege('anon',p.oid,'execute') and not has_function_privilege('service_role',p.oid,'execute') and not exists(select 1 from aclexplode(p.proacl) x where x.grantee=0)) then '예' else '아니오' end
union all select 'log table privileges unchanged',case when has_table_privilege('authenticated','public.app_mcp_write_log','select') and not has_table_privilege('authenticated','public.app_mcp_write_log','insert,delete,truncate,references,trigger') and (select count(*) from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_write_log') and a.attnum>0 and not a.attisdropped and has_column_privilege('authenticated',a.attrelid,a.attnum,'update'))=1 and not has_table_privilege('anon','public.app_mcp_write_log','select,insert,update,delete,truncate,references,trigger') and not has_table_privilege('service_role','public.app_mcp_write_log','select,insert,update,delete,truncate,references,trigger') then '예' else '아니오' end
union all select 'existing boundary hash',md5(coalesce((select string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid))||coalesce(p.proacl::text,''),',' order by p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname in('public','private') and p.proname like 'app\_mcp\_%' and p.proname not in ('app_mcp_write_gate','app_mcp_write_undo','app_mcp_attach_check','app_mcp_attach_commit','app_mcp_attach_undone')) or p.oid in (to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('private.app_is_workspace_owner(uuid)'))),'')||coalesce((select string_agg(c.relname::text||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before'),to_regclass('public.app_operator_features'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_write_log'),to_regclass('public.app_mcp_write_before'),to_regclass('public.app_operator_features'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(t.tgrelid::regclass::text||t.tgname::text||t.tgenabled::text,',' order by t.tgrelid::regclass::text,t.tgname) from pg_trigger t where not t.tgisinternal and t.tgrelid in (to_regclass('public.app_notes'),to_regclass('public.app_mcp_write_log'))),''));
